#!/bin/bash
# Rebuild every media artifact from the real judge outputs.
#
#   data/verdicts/*.json   committed judge outputs (grade.sh --seed 42);
#                          regenerated by collect_verdicts.sh if missing
#   work/<case>/job.frd    real ccx runs, re-done here via judge.py's own
#                          gen_mesh/parse_frd (cached by content stamp)
#   work/run_logs/         this run's real console logs + measured wall
#                          seconds (setup/selftest/grade); captured once
#   result.png loop.png    matplotlib figures
#   clips/*.mp4            real motion clips rendered by render_clips.py
#                          (orbiting 3-D views of the ccx field + the
#                          console replay) -- git-ignored intermediates
#   video/index.html       HyperFrames composition (gen_composition.py
#                          injects the verdict numbers; nothing is typed)
#   demo.mp4               hyperframes render -> master -> H.264 web encode
#   MANIFEST.json          sha256 + provenance for each file
#
# Requires: judge/setup.sh already run (ccx, gmsh in ~/tools/bin),
# ffmpeg on PATH (distro build), and Node.js >= 22 with npx for the
# HyperFrames render (media/video/package.json pins hyperframes exactly;
# npm ci installs it). Python deps are pinned in media/requirements.txt
# and installed into media/.venv (git-ignored).
set -euo pipefail
MEDIA="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
DEMO="$(dirname "$MEDIA")"
export PATH="$HOME/tools/bin:$PATH"
PY="$MEDIA/.venv/bin/python"

die() { echo "make_media: $*" >&2; exit 1; }

# --- toolchain -------------------------------------------------------------
command -v ffmpeg >/dev/null || die "ffmpeg missing (distro package)"
command -v ccx  >/dev/null || die "ccx missing -- run judge/setup.sh first"
command -v gmsh >/dev/null || die "gmsh missing -- run judge/setup.sh first"
command -v npx  >/dev/null || die "npx missing -- need Node.js >= 22"
if [ ! -x "$PY" ]; then
    echo "== create media/.venv with pinned deps =="
    python3 -m venv "$MEDIA/.venv"
    "$MEDIA/.venv/bin/pip" install -q -r "$MEDIA/requirements.txt"
fi

# --- judge outputs ----------------------------------------------------------
# verdicts are committed under data/verdicts; regenerate only if absent
if ! ls "$MEDIA"/data/verdicts/*.json >/dev/null 2>&1; then
    echo "== verdict JSONs missing -> collecting via real grading =="
    bash "$MEDIA/collect_verdicts.sh"
fi
for f in good units-in-metres propped-tip load-on-ntip coarse-mesh \
         unconverged load-wrong-dof overload-10x undersized \
         no-stress-output; do
    [ -f "$MEDIA/data/verdicts/$f.json" ] || die "missing verdict $f.json"
done

# mutants must exist for the field solves
if [ ! -f "$MEDIA/work/mutants/overload-10x/beam.inp" ]; then
    mkdir -p "$MEDIA/work/mutants"
    python3 "$DEMO/judge/mutants.py" "$MEDIA/work/mutants" >/dev/null
fi

# --- real fields ------------------------------------------------------------
echo "== solve real .frd fields (ccx) =="
"$PY" "$MEDIA/solve_fields.py"
[ -f "$MEDIA/work/good-fine/job.frd" ] || die "good-fine job.frd missing"
[ -f "$MEDIA/data/convergence.json" ] || die "convergence.json missing"

# --- this run's console logs (footage for the terminal clip) ---------------
# captured once: the terminal clip replays what THIS sandbox printed.
# delete media/work/run_logs/ to re-record.
if [ ! -f "$MEDIA/work/run_logs/timing.json" ]; then
    echo "== capture run logs (setup/selftest/grade, measured) =="
    mkdir -p "$MEDIA/work/run_logs"
    L="$MEDIA/work/run_logs"
    S=$(date +%s); bash "$DEMO/judge/setup.sh" > "$L/setup.log" 2>&1
    E=$(date +%s); setup_s=$((E-S))
    S=$(date +%s); bash "$DEMO/judge/selftest.sh" > "$L/selftest.log" 2>&1
    E=$(date +%s); selftest_s=$((E-S))
    S=$(date +%s); bash "$DEMO/judge/grade.sh" "$DEMO/examples/good" \
        --seed 42 > "$L/grade.log" 2>&1
    E=$(date +%s); grade_s=$((E-S))
    cat > "$L/timing.json" <<EOF
{"setup_s": $setup_s, "selftest_s": $selftest_s, "grade_s": $grade_s,
 "source": "measured wall seconds of this media build's own judge steps"}
EOF
fi

# --- figures ----------------------------------------------------------------
echo "== result.png =="
"$PY" "$MEDIA/fig_result.py"
echo "== loop.png =="
"$PY" "$MEDIA/fig_loop.py"

# --- motion clips -----------------------------------------------------------
echo "== clips/*.mp4 (real ccx field, orbiting camera; console replay) =="
"$PY" "$MEDIA/render_clips.py"

# --- composition + render ----------------------------------------------------
echo "== video/index.html (numbers injected from this run's outputs) =="
"$PY" "$MEDIA/gen_composition.py"

echo "== npm ci (pinned hyperframes) =="
( cd "$MEDIA/video" && npm ci --no-audit --no-fund )

echo "== hyperframes render (headless Chrome -> master mp4) =="
mkdir -p "$MEDIA/master"
( cd "$MEDIA/video" && npx hyperframes render . \
    -o "$MEDIA/master/demo_hf.mp4" --crf 16 )

# --- web encode ---------------------------------------------------------------
echo "== demo.mp4 (H.264 yuv420p, crf 18, +faststart) =="
ffmpeg -y -v error -i "$MEDIA/master/demo_hf.mp4" \
    -c:v libx264 -preset slow -crf 18 -pix_fmt yuv420p \
    -movflags +faststart -an "$MEDIA/demo.mp4"

# --- manifest ---------------------------------------------------------------
"$PY" "$MEDIA/manifest.py"
echo "make_media: done -> $MEDIA/{result.png,loop.png,demo.mp4,MANIFEST.json}"
